<main class="content container-fluid"><section class="card panel-card"><div class="card-body p-4 p-xl-5"><div class="d-flex flex-column flex-md-row align-items-md-center justify-content-between gap-3 mb-4"><div><span class="eyebrow">GESTIÓN DE PERSONAS</span><h2 class="mt-2 mb-1">Usuarios y docentes</h2><p class="text-secondary mb-0">Consulta, edita y administra las cuentas de la plataforma.</p></div><a class="btn btn-brand btn-lg" href="<?=url('/admin/usuarios/formulario')?>">+ Nuevo usuario</a></div><div class="table-responsive rounded-4 border"><table class="table table-hover align-middle mb-0"><thead><tr><th>Nombre</th><th>Contacto</th><th>Rol</th><th>Asignatura</th><th>Permisos</th><th>Acciones</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['first_name'].' '.$u['last_name'])?></strong></td><td><?=e($u['email'])?><span class="table-note"><?=e($u['phone']?:'Sin teléfono')?></span></td><td><span class="badge badge-soft-purple"><?=e(ucfirst($u['role']))?></span></td><td><?=e($u['subject']??'—')?></td><td><span class="badge <?=$u['test_enabled']?'text-bg-success':'text-bg-light'?>">Tests</span> <span class="badge <?=$u['tabulator_enabled']?'text-bg-success':'text-bg-light'?>">Tabuladores</span></td><td><div class="d-flex flex-wrap gap-2"><a class="btn btn-sm btn-outline-success" href="<?=url('/admin/usuarios/ver?id='.$u['id'])?>">Ver</a><a class="btn btn-sm btn-outline-primary" href="<?=url('/admin/usuarios/formulario?id='.$u['id'])?>">Editar</a><form method="post" action="<?=url('/admin/usuarios/eliminar')?>" onsubmit="return confirm('¿Eliminar este usuario?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form></div></td></tr><?php endforeach;?></tbody></table></div></div></section></main>
